THOUGHT: Both implementations look correct. Let me re-read the PR description more carefully to understand what the actual problem is.

The PR says: "QueryWith function returns empty query when ToSql succeeds". But looking at the code, that doesn't seem to be the case. Let me create a simple test program based on the example in the PR description to verify the behavior:

```bash
cat <<'EOF' > test_issue.go
package main

import (
    "database/sql"
    "fmt"
    "github.com/Masterminds/squirrel"
    _ "github.com/lib/pq"
)

type mockDB struct{}

func (m *mockDB) Query(query string, args ...interface{}) (*sql.Rows, error) {
    fmt.Printf("Query executed: %s\n", query)
    return nil, nil
}

func (m *mockDB) Exec(query string, args ...interface{}) (sql.Result, error) {
    return nil, nil
}

func main() {
    db := &mockDB{}

    // Create a simple select query
    query := squirrel.Select("test")

    // This should execute the query but doesn't
    rows, err := squirrel.QueryWith(db, query)
    if err != nil {
        fmt.Printf("Error: %v\n", err)
    }

    // Expected: "Query executed: SELECT test"
    // Actual: Nothing printed (query not executed)

    fmt.Printf("Rows: %v\n", rows)
}
EOF
```

